from datetime import date, datetime
from decimal import Decimal, InvalidOperation

_BUCKETS = ("current", "1-30", "31-60", "61-90", "90+")
_QUANT = Decimal("0.00")

def _parse_date_value(value, *, is_as_of=False):
    # datetime is subclass of date: for as_of it must raise, for due_date normalize to date
    if isinstance(value, datetime):
        if is_as_of:
            raise ValueError(f"invalid as_of datetime: {value!r}")
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        # Strict YYYY-MM-DD only for both as_of and due_date
        if len(value) != 10 or value[4] != "-" or value[7] != "-":
            raise ValueError(f"unparseable date string: {value!r}")
        if not (value[0:4].isdigit() and value[5:7].isdigit() and value[8:10].isdigit()):
            raise ValueError(f"unparseable date string: {value!r}")
        try:
            return date.fromisoformat(value)
        except Exception:
            raise ValueError(f"unparseable date string: {value!r}")
    raise ValueError(f"invalid date: {value!r}")

def _parse_amount(value):
    # bool is subclass of int: reject explicitly
    if isinstance(value, bool):
        raise ValueError(f"invalid amount: {value!r}")
    if isinstance(value, float):
        raise ValueError(f"float amount not allowed: {value!r}")
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError(f"non-finite amount: {value!r}")
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        try:
            d = Decimal(value)
        except (InvalidOperation, ValueError, AttributeError, TypeError):
            raise ValueError(f"unparseable amount: {value!r}")
        except Exception:
            raise ValueError(f"unparseable amount: {value!r}")
        if not d.is_finite():
            raise ValueError(f"non-finite amount: {value!r}")
        return d
    raise ValueError(f"invalid amount: {value!r}")

def _sum_quantize(values):
    # Exact sum of finite Decimals then ROUND_HALF_EVEN to exponent -2
    # using unbounded integer arithmetic to avoid context precision limits.
    if not values:
        return Decimal("0.00")
    coeffs_exps = []
    for d in values:
        if d == 0:
            continue
        t = d.as_tuple()
        exp = t.exponent
        coeff_str = "".join(str(x) for x in t.digits)
        coeff = int(coeff_str)
        if t.sign:
            coeff = -coeff
        coeffs_exps.append((coeff, exp))
    if not coeffs_exps:
        return Decimal("0.00")
    min_exp = min(e for _, e in coeffs_exps)
    total = 0
    for coeff, exp in coeffs_exps:
        total += coeff * (10 ** (exp - min_exp))
    if total == 0:
        return Decimal("0.00")
    target_exp = -2
    if min_exp >= target_exp:
        scaled = total * (10 ** (min_exp - target_exp))
        return Decimal(f"{scaled}E{target_exp}")
    k = target_exp - min_exp
    divisor = 10 ** k
    sign = -1 if total < 0 else 1
    a = abs(total)
    q, r = divmod(a, divisor)
    twice = r * 2
    if twice < divisor:
        rounded = q
    elif twice > divisor:
        rounded = q + 1
    else:
        rounded = q if (q % 2 == 0) else q + 1
    rounded *= sign
    return Decimal(f"{rounded}E{target_exp}")

def aging_buckets(invoices: list[dict], as_of: date) -> dict[str, Decimal]:
    as_of_date = _parse_date_value(as_of, is_as_of=True)
    bucket_values: dict[str, list] = {k: [] for k in _BUCKETS}
    # invoices must be iterable of dicts
    try:
        items = list(invoices)
    except TypeError:
        raise ValueError("invoices must be a list")
    for inv in items:
        if not isinstance(inv, dict):
            raise ValueError(f"invalid invoice: {inv!r}")
        try:
            due_raw = inv["due_date"]
        except KeyError:
            raise ValueError("missing due_date")
        try:
            amt_raw = inv["amount"]
        except KeyError:
            raise ValueError("missing amount")
        due_date = _parse_date_value(due_raw)
        amount = _parse_amount(amt_raw)
        days_overdue = (as_of_date - due_date).days
        if days_overdue <= 0:
            bucket = "current"
        elif 1 <= days_overdue <= 30:
            bucket = "1-30"
        elif 31 <= days_overdue <= 60:
            bucket = "31-60"
        elif 61 <= days_overdue <= 90:
            bucket = "61-90"
        else:
            bucket = "90+"
        bucket_values[bucket].append(amount)
    # exact sum + quantize to exactly 2 decimals, preserve key order
    result: dict[str, Decimal] = {}
    for k in _BUCKETS:
        result[k] = _sum_quantize(bucket_values[k])
    return result
